package com.gymmind.workout.application;

import com.gymmind.exercise.domain.repository.ExerciseRepository;
import com.gymmind.iam.domain.model.RoleCode;
import com.gymmind.member.domain.repository.MemberRepository;
import com.gymmind.shared.error.*;
import com.gymmind.shared.security.*;
import com.gymmind.workout.domain.model.*;
import com.gymmind.workout.domain.repository.*;
import com.gymmind.workout.infrastructure.persistence.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDate;
import java.util.*;

@Service
public class DefaultTrainingPlanService implements TrainingPlanService {
 private final SpringDataWorkoutPlanTemplateRepository templates; private final SpringDataWorkoutPlanTemplateItemRepository templateItems;
 private final SpringDataMemberWorkoutPlanRepository legacyMemberPlans; private final SpringDataMemberWorkoutScheduleRepository schedules;
 private final MemberRepository members; private final ExerciseRepository exercises; private final WorkoutPlanRepository plans; private final WorkoutPlanItemRepository planItems;
 public DefaultTrainingPlanService(SpringDataWorkoutPlanTemplateRepository t,SpringDataWorkoutPlanTemplateItemRepository i,SpringDataMemberWorkoutPlanRepository p,SpringDataMemberWorkoutScheduleRepository s,MemberRepository m,ExerciseRepository e,WorkoutPlanRepository wp,WorkoutPlanItemRepository wi){templates=t;templateItems=i;legacyMemberPlans=p;schedules=s;members=m;exercises=e;plans=wp;planItems=wi;}
 private Long tenant(CurrentActor a){Long t=ActorAccess.tenantId(a);if(t==null)throw new BusinessException(ErrorCode.TENANT_CONTEXT_REQUIRED);return t;}
 private Long member(CurrentActor a){return members.findByTenantIdAndUserId(tenant(a),a.userId()).map(x->x.getId()).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));}
 private void coach(CurrentActor a){if(a==null||!a.roles().contains(RoleCode.COACH)||!a.hasPermission("workout:write"))throw new BusinessException(ErrorCode.FORBIDDEN);}
 private void memberReader(CurrentActor a){if(a==null||!a.roles().contains(RoleCode.MEMBER)||!a.hasPermission("workout:read"))throw new BusinessException(ErrorCode.FORBIDDEN);}
 private void reader(CurrentActor a){if(a==null||!a.hasPermission("workout:read"))throw new BusinessException(ErrorCode.FORBIDDEN);tenant(a);}
 @Transactional(readOnly=true) public List<?> templates(CurrentActor a){reader(a);return templates.findAllByTenantIdAndStatus(tenant(a),WorkoutPlanTemplateStatus.PUBLISHED);}
 @Transactional(readOnly=true) public Object template(CurrentActor a,Long id){reader(a);Long t=tenant(a);var p=templates.findByTenantIdAndId(t,id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));var d=new LinkedHashMap<String,Object>();d.put("id",p.getId());d.put("name",p.getName());d.put("category",p.getCategory());d.put("goal",p.getGoal());d.put("description",p.getDescription());d.put("coachId",p.getCoachId());d.put("versionNumber",p.getVersionNumber());d.put("status",p.getStatus());d.put("items",templateItems.findAllByTemplateIdOrderBySortOrder(p.getId()).stream().map(i->{var x=new LinkedHashMap<String,Object>();String n=i.getExerciseName();if((n==null||n.isBlank())&&i.getExerciseId()!=null)n=exercises.findByTenantIdAndId(t,i.getExerciseId()).map(e->e.getName()).orElse("动作 #"+i.getExerciseId());x.put("id",i.getId());x.put("exerciseId",i.getExerciseId());x.put("exerciseName",n);x.put("phase",i.getPhase());x.put("sortOrder",i.getSortOrder());x.put("sets",i.getSets());x.put("reps",i.getReps());x.put("restSeconds",i.getRestSeconds());x.put("weight",i.getWeight());x.put("notes",i.getNotes());return x;}).toList());return d;}
 @Transactional public Object create(CurrentActor a,CreateTemplateCommand c){coach(a);Long t=tenant(a);if(c==null||c.name()==null||c.name().isBlank()||c.category()==null||c.category().isBlank()||c.goal()==null||c.goal().isBlank()||c.description()==null||c.description().isBlank()||c.items()==null||c.items().isEmpty())throw new BusinessException(ErrorCode.VALIDATION_FAILED);for(var x:c.items())if(x==null||((x.exerciseName()==null||x.exerciseName().isBlank())&&x.exerciseId()==null)||x.phase()==null||!Set.of("WARMUP","MAIN","STRETCH").contains(x.phase())||x.sets()<1||x.reps()<1||x.restSeconds()<0||x.weight()<0||x.sortOrder()<0||(x.exerciseId()!=null&&exercises.findByTenantIdAndId(t,x.exerciseId()).isEmpty()))throw new BusinessException(ErrorCode.VALIDATION_FAILED);var p=templates.save(new WorkoutPlanTemplate(t,a.userId(),c.name(),c.category(),c.goal(),c.description()));int n=0;for(var x:c.items()){String name=x.exerciseName();if(name==null||name.isBlank())name=exercises.findByTenantIdAndId(t,x.exerciseId()).map(e->e.getName()).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));templateItems.save(new WorkoutPlanTemplateItem(p,x.exerciseId(),name,x.phase(),x.sortOrder()>0?x.sortOrder():++n,x.sets(),x.reps(),x.restSeconds(),x.weight(),x.notes()));}return p;}
 @Transactional public Object publish(CurrentActor a,Long id){coach(a);var p=templates.findByTenantIdAndId(tenant(a),id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));if(!Objects.equals(p.getCoachId(),a.userId())||p.getStatus()!=WorkoutPlanTemplateStatus.DRAFT)throw new BusinessException(ErrorCode.FORBIDDEN);p.publish();return p;}
 @Transactional public Object select(CurrentActor a,Long id){memberReader(a);Long t=tenant(a),m=member(a);var p=templates.findByTenantIdAndId(t,id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));if(p.getStatus()!=WorkoutPlanTemplateStatus.PUBLISHED)throw new BusinessException(ErrorCode.FORBIDDEN);LocalDate d=LocalDate.now();var copy=plans.save(WorkoutPlan.create(t,m,p.getCoachId(),p.getName(),p.getGoal(),d,d.plusMonths(1),p.getDescription()));int n=0;for(var x:templateItems.findAllByTemplateIdOrderBySortOrder(p.getId())){String name=x.getExerciseName();if(name==null||name.isBlank())name=exercises.findByTenantIdAndId(t,x.getExerciseId()).map(e->e.getName()).orElse("动作 #"+x.getExerciseId());planItems.save(WorkoutPlanItem.create(copy,x.getExerciseId(),name,1,x.getSets(),x.getReps(),x.getRestSeconds(),x.getWeight(),x.getNotes(),x.getPhase(),x.getSortOrder()>0?x.getSortOrder():++n));}return copy;}
 @Transactional(readOnly=true) public List<?> memberPlans(CurrentActor a){memberReader(a);Long m=member(a);return plans.findAllByTenantId(tenant(a)).stream().filter(p->m.equals(p.getMemberId())).toList();}
 @Transactional public Object schedule(CurrentActor a,Long id,LocalDate date){memberReader(a);Long t=tenant(a),m=member(a);if(date==null)throw new BusinessException(ErrorCode.VALIDATION_FAILED);if(plans.findByTenantIdAndId(t,id).filter(p->m.equals(p.getMemberId())).isPresent())return schedules.save(MemberWorkoutSchedule.forWorkoutPlan(t,id,m,date));var legacy=legacyMemberPlans.findByTenantIdAndId(t,id).filter(p->m.equals(p.getMemberId())).orElseThrow(()->new BusinessException(ErrorCode.FORBIDDEN));return schedules.save(legacy.getWorkoutPlanId()==null?new MemberWorkoutSchedule(t,id,m,date):MemberWorkoutSchedule.forWorkoutPlan(t,legacy.getWorkoutPlanId(),m,date));}
 @Transactional(readOnly=true) public List<MemberWorkoutScheduleView> calendar(CurrentActor a,LocalDate f,LocalDate to){memberReader(a);Long t=tenant(a);return schedules.findAllByTenantIdAndMemberIdAndScheduledDateBetween(t,member(a),f,to).stream().map(s->toScheduleView(t,s)).toList();}
 private MemberWorkoutScheduleView toScheduleView(Long tenantId,MemberWorkoutSchedule schedule){String planName=null;String goal=null;Long workoutPlanId=schedule.getWorkoutPlanId();if(workoutPlanId!=null){var plan=plans.findByTenantIdAndId(tenantId,workoutPlanId);if(plan.isPresent()){planName=plan.get().getName();goal=plan.get().getGoal();}}if((planName==null||planName.isBlank())&&schedule.getMemberPlanId()!=null){var legacy=legacyMemberPlans.findByTenantIdAndId(tenantId,schedule.getMemberPlanId());if(legacy.isPresent()){planName=legacy.get().getName();if(workoutPlanId==null){workoutPlanId=legacy.get().getWorkoutPlanId();}}}if(planName==null||planName.isBlank()){planName=workoutPlanId!=null?"训练计划 #"+workoutPlanId:"训练计划";}return new MemberWorkoutScheduleView(schedule.getId(),schedule.getMemberPlanId(),workoutPlanId,schedule.getMemberId(),schedule.getScheduledDate(),planName,goal);}
 @Transactional public void deleteSchedule(CurrentActor a,Long id){memberReader(a);var s=schedules.findByTenantIdAndId(tenant(a),id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));if(!s.getMemberId().equals(member(a)))throw new BusinessException(ErrorCode.FORBIDDEN);schedules.delete(s);}
}
